    },
    {
      "card_ids": ["C11"],
      "claim": "Ofloxacin reached high CSF/serum ratios (53-71%) in meningitis patients after oral dosing, but this reflects inflamed-meninges conditions and is discounted as disrupted-barrier evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted fail: the preponderance of transferred direct systemic exposure evidence shows low brain/CSF penetration in healthy-barrier models; positive CSF findings are from meningitis/inflamed-barrier conditions and are discounted.",
  "evidence_gaps": [
    "Most direct evidence is from rodent healthy-barrier studies; human CSF data are from meningitis/inflamed barrier, limiting transfer to normal CNS access.",
    "Molecule 3 grouping includes levofloxacin (C12) under ofloxacin, a provenance conflict; inconsistent card was discounted.",
    "No direct healthy human brain or CSF pharmacokinetic data are available among the transferred records."
  ],
